import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router, NavigationEnd } from '@angular/router';
import { filter } from 'rxjs/operators';
import { FinanceService, VenteService } from '../../core/services/api.service';

@Component({
  selector: 'app-caisses',
  standalone: true,
  imports: [CommonModule, FormsModule],
  template: `
    <div class="page-container">
      <div class="page-header">
        <div>
          <h3>🏦 Caisses</h3>
          <p class="subtitle">Suivi des soldes de caisse et des ventes</p>
        </div>
        <button class="btn btn-primary" (click)="load()">🔄 Actualiser</button>
      </div>

      <!-- Soldes Overview -->
      <div class="soldes-grid">
        <div class="solde-card" *ngFor="let c of caisses">
          <div class="solde-header">
            <span class="solde-icon">🏦</span>
            <div>
              <strong>{{ c.nom }}</strong>
              <small>{{ c.stock_nom }}</small>
            </div>
          </div>
          <div class="soldes-details">
            <div class="solde-row">
              <span class="solde-label">💵 Espèces:</span>
              <span class="solde-value">{{ c.solde_especes || 0 | number:'1.0-0' }} FCA</span>
            </div>
            <div class="solde-row">
              <span class="solde-label">📱 Orange Money:</span>
              <span class="solde-value om">{{ c.solde_orange_money || 0 | number:'1.0-0' }} FCA</span>
            </div>
            <div class="solde-row">
              <span class="solde-label">🌊 Wave:</span>
              <span class="solde-value wave">{{ c.solde_wave || 0 | number:'1.0-0' }} FCA</span>
            </div>
            <div class="solde-row">
              <span class="solde-label">💳 Carte:</span>
              <span class="solde-value carte">{{ c.solde_carte || 0 | number:'1.0-0' }} FCA</span>
            </div>
            <div class="solde-row total">
              <span class="solde-label">📊 Total:</span>
              <span class="solde-value">{{ c.solde || 0 | number:'1.0-0' }} FCA</span>
            </div>
          </div>
          <div class="solde-actions">
            <button class="btn btn-sm btn-success" (click)="ajuster(c, 'entree')">+ Entrée</button>
            <button class="btn btn-sm btn-danger" (click)="ajuster(c, 'sortie')">- Sortie</button>
            <button class="btn btn-sm btn-info" (click)="voirHistorique(c)">📋 Historique</button>
          </div>
        </div>
      </div>

      <!-- Stats des ventes -->
      <div class="stats-row" style="margin-bottom: 20px;">
        <div class="stat-card green">
          <strong>{{ totalPaye | number:'1.0-0' }} FCA</strong>
          <small>Total Payé</small>
        </div>
        <div class="stat-card red">
          <strong>{{ totalCredit | number:'1.0-0' }} FCA</strong>
          <small>Total Crédit</small>
        </div>
        <div class="stat-card blue">
          <strong>{{ totalVentes }}</strong>
          <small>Nombre de Ventes</small>
        </div>
      </div>

      <!-- Buttons -->
      <div style="margin-bottom: 20px; display: flex; gap: 10px; flex-wrap: wrap;">
        <button class="btn" [class.btn-success]="showWhat === 'paye'" [class.btn-secondary]="showWhat !== 'paye'" (click)="showWhat = 'paye'">
          ✅ Payé ({{ ventesPayees.length }})
        </button>
        <button class="btn" [class.btn-danger]="showWhat === 'credit'" [class.btn-secondary]="showWhat !== 'credit'" (click)="showWhat = 'credit'">
          ❌ Crédit ({{ ventesCredits.length }})
        </button>
        <button class="btn" [class.btn-info]="showWhat === 'partiel'" [class.btn-secondary]="showWhat !== 'partiel'" (click)="showWhat = 'partiel'">
          💰 Partiel ({{ ventesPartiels.length }})
        </button>
      </div>

      <!-- Ventes payées -->
      <div class="card" *ngIf="showWhat === 'paye'">
        <div class="card-header">
          <h4>✅ Ventes Payées - Total: {{ getTotalPaye() | number:'1.0-0' }} FCA</h4>
        </div>
        <table class="table">
          <thead>
            <tr><th>N°</th><th>Client</th><th>Stock</th><th>Montant</th><th>Payé</th><th>Mode</th><th>Date</th></tr>
          </thead>
          <tbody>
            <tr *ngFor="let v of ventesPayees">
              <td>{{ v.numero }}</td>
              <td>{{ v.client_nom }}</td>
              <td>{{ v.stock_nom }}</td>
              <td>{{ v.montant_total | number:'1.0-0' }} FCA</td>
              <td class="text-success">{{ v.montant_paye | number:'1.0-0' }} FCA</td>
              <td>{{ getModeLabel(v.mode_paiement) }}</td>
              <td>{{ v.date_vente | date:'dd/MM/yyyy' }}</td>
            </tr>
            <tr *ngIf="ventesPayees.length === 0">
              <td colspan="7" class="text-center">Aucune vente payée</td>
            </tr>
          </tbody>
        </table>
      </div>

      <!-- Ventes crédit -->
      <div class="card" *ngIf="showWhat === 'credit'">
        <div class="card-header">
          <h4>❌ Ventes en Crédit - Total: {{ getTotalCredit() | number:'1.0-0' }} FCA</h4>
        </div>
        <table class="table">
          <thead>
            <tr><th>N°</th><th>Client</th><th>Stock</th><th>Montant</th><th>Reste</th><th>Date</th><th>Action</th></tr>
          </thead>
          <tbody>
            <tr *ngFor="let v of ventesCredits">
              <td>{{ v.numero }}</td>
              <td>{{ v.client_nom }}</td>
              <td>{{ v.stock_nom }}</td>
              <td>{{ v.montant_total | number:'1.0-0' }} FCA</td>
              <td class="text-danger">{{ v.montant_restant | number:'1.0-0' }} FCA</td>
              <td>{{ v.date_vente | date:'dd/MM/yyyy' }}</td>
              <td><button class="btn btn-sm btn-success" (click)="enregistrerPaiement(v)">💳 Payer</button></td>
            </tr>
            <tr *ngIf="ventesCredits.length === 0">
              <td colspan="7" class="text-center">Aucune vente en crédit</td>
            </tr>
          </tbody>
        </table>
      </div>

      <!-- Ventes partiel -->
      <div class="card" *ngIf="showWhat === 'partiel'">
        <div class="card-header">
          <h4>💰 Ventes Paiement Partiel</h4>
        </div>
        <table class="table">
          <thead>
            <tr><th>N°</th><th>Client</th><th>Stock</th><th>Montant</th><th>Payé</th><th>Reste</th><th>Date</th><th>Action</th></tr>
          </thead>
          <tbody>
            <tr *ngFor="let v of ventesPartiels">
              <td>{{ v.numero }}</td>
              <td>{{ v.client_nom }}</td>
              <td>{{ v.stock_nom }}</td>
              <td>{{ v.montant_total | number:'1.0-0' }} FCA</td>
              <td class="text-success">{{ v.montant_paye | number:'1.0-0' }} FCA</td>
              <td class="text-danger">{{ v.montant_restant | number:'1.0-0' }} FCA</td>
              <td>{{ v.date_vente | date:'dd/MM/yyyy' }}</td>
              <td><button class="btn btn-sm btn-success" (click)="enregistrerPaiement(v)">💳 Payer</button></td>
            </tr>
            <tr *ngIf="ventesPartiels.length === 0">
              <td colspan="8" class="text-center">Aucune vente partiel</td>
            </tr>
          </tbody>
        </table>
      </div>

      <!-- Mouvements -->
      <div class="card">
        <div class="card-header">
          <h4>📋 Historique des mouvements</h4>
        </div>
        <table class="table">
          <thead>
            <tr><th>Type</th><th>Source</th><th>Montant</th><th>Description</th><th>Date</th></tr>
          </thead>
          <tbody>
            <tr *ngFor="let m of mouvements">
              <td><span class="badge" [class.badge-success]="m.type === 'entree'" [class.badge-danger]="m.type === 'sortie'">{{ m.type === 'entree' ? 'Entrée' : 'Sortie' }}</span></td>
              <td>{{ m.source }}</td>
              <td [class.text-danger]="m.type === 'sortie'" [class.text-success]="m.type === 'entree'">{{ m.montant | number:'1.0-0' }} FCA</td>
              <td>{{ m.description }}</td>
              <td>{{ m.date_mouvement | date:'dd/MM/yyyy HH:mm' }}</td>
            </tr>
            <tr *ngIf="mouvements.length === 0">
              <td colspan="5" class="text-center">Aucun mouvement</td>
            </tr>
          </tbody>
        </table>
      </div>

      <!-- Paiement Modal -->
      <div class="modal-overlay" *ngIf="showPaiement" (click)="showPaiement=false">
        <div class="modal-card" style="max-width:400px" (click)="$event.stopPropagation()">
          <div class="modal-header">
            <h4>💳 Enregistrer Paiement</h4>
            <button class="close-btn" (click)="showPaiement=false">✕</button>
          </div>
          <div class="modal-form" *ngIf="selectedVente">
            <div class="vente-info-box">
              <p><strong>Vente:</strong> {{ selectedVente.numero }}</p>
              <p><strong>Client:</strong> {{ selectedVente.client_nom }}</p>
              <p><strong>Total:</strong> {{ selectedVente.montant_total | number:'1.0-0' }} FCA</p>
              <p><strong>Déjà payé:</strong> {{ selectedVente.montant_paye | number:'1.0-0' }} FCA</p>
              <p><strong>Restant dû:</strong> <span style="color:red">{{ selectedVente.montant_restant | number:'1.0-0' }} FCA</span></p>
            </div>
            <div class="form-group">
              <label>Montant à payer (FCFA)</label>
              <input type="number" [(ngModel)]="paiementMontant" [max]="selectedVente.montant_restant" min="0" />
            </div>
            <div class="form-group">
              <label>Mode de Paiement</label>
              <select [(ngModel)]="paiementMode">
                <option value="espece">Espèce</option>
                <option value="orange_money">Orange Money</option>
                <option value="wave">Wave</option>
                <option value="carte">Carte Bancaire</option>
              </select>
            </div>
            <div class="modal-footer">
              <button class="btn btn-secondary" (click)="showPaiement=false">Annuler</button>
              <button class="btn btn-success" (click)="confirmPaiement()">✓ Valider</button>
            </div>
          </div>
        </div>
      </div>

      <!-- Ajustement Modal -->
      <div class="modal-overlay" *ngIf="showAjust" (click)="showAjust=false">
        <div class="modal-card" style="max-width:400px" (click)="$event.stopPropagation()">
          <div class="modal-header">
            <h4>{{ ajustType === 'entree' ? '+ Entrée Caisse' : '- Sortie Caisse' }}</h4>
            <button class="close-btn" (click)="showAjust=false">✕</button>
          </div>
          <div class="modal-form">
            <div class="form-group">
              <label>Montant (FCFA) *</label>
              <input type="number" [(ngModel)]="ajustMontant" min="1" />
            </div>
            <div class="form-group">
              <label>Mode de paiement</label>
              <select [(ngModel)]="ajustMode">
                <option value="espece">Espèces</option>
                <option value="orange_money">Orange Money</option>
                <option value="wave">Wave</option>
                <option value="carte">Carte</option>
              </select>
            </div>
            <div class="form-group">
              <label>Description</label>
              <input type="text" [(ngModel)]="ajustDescription" placeholder="Motif..." />
            </div>
            <div class="modal-footer">
              <button class="btn btn-secondary" (click)="showAjust=false">Annuler</button>
              <button class="btn btn-primary" (click)="confirmAjust()">Valider</button>
            </div>
          </div>
        </div>
      </div>
    </div>
  `,
  styles: [`
    .stats-row { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; margin-bottom: 24px; }
    .stat-card { background: white; border-radius: 12px; padding: 16px 20px; border-left: 4px solid; box-shadow: 0 2px 8px rgba(0,0,0,0.05); }
    .stat-card.green { border-color: #10b981; }
    .stat-card.blue { border-color: #3b82f6; }
    .stat-card.red { border-color: #ef4444; }
    .stat-card strong { display: block; font-size: 20px; font-weight: 800; }
    .stat-card small { color: #999; font-size: 12px; }
    .soldes-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 16px; margin-bottom: 24px; }
    .solde-card { background: white; border-radius: 14px; padding: 20px; border: 1px solid #f0f0f0; box-shadow: 0 2px 8px rgba(0,0,0,0.05); }
    .solde-header { display: flex; align-items: center; gap: 12px; margin-bottom: 16px; }
